package com.pratik.imagetap;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.SystemClock;import android.view.*;import android.widget.*;import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w412dp-h892dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class AutoBashUiTest {
 org.robolectric.android.controller.ActivityController<MainActivity> ctl;MainActivity a;
 @Before public void setup(){RuntimeEnvironment.getApplication().getSharedPreferences("config",0).edit().putBoolean("reduceMotion",true).commit();ctl=Robolectric.buildActivity(MainActivity.class).setup();a=ctl.get();}
 @After public void close(){a.finish();ctl.pause().stop().destroy();}
 View root(){return ((ViewGroup)a.findViewById(android.R.id.content)).getChildAt(0);}
 @Test public void brainOpensMenuAndRoutesToImages()throws Exception{OrbitMenu menu=findOrbit(root());assertNotNull(menu);assertFalse(menu.isOpen());assertNotNull(find(root(),"AutoBash"));assertNull(find(root(),"Ready when\nyou are."));menu.brain.performClick();assertTrue(menu.isOpen());for(View node:menu.destinations){assertEquals(View.VISIBLE,node.getVisibility());assertTrue(node.isFocusable());}save(root(),"autobash-orbit",824,1656);menu.destinations[0].performClick();assertNotNull(find(root(),"Choose an action."));}
 @Test public void orbitPresetsAndBackWork(){OrbitMenu menu=findOrbit(root());menu.brain.performClick();menu.destinations[2].performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(d.isShowing());d.dismiss();a.onBackPressed();assertFalse(menu.isOpen());assertFalse(a.isFinishing());}
 @Test public void expandedMenuSurvivesRotation(){findOrbit(root()).brain.performClick();ctl.recreate();a=ctl.get();assertTrue(findOrbit(root()).isOpen());}
 @Test @Config(qualifiers="w320dp-h600dp-xhdpi") public void compactMenuTargetsRemainInsideBounds()throws Exception{OrbitMenu menu=findOrbit(root());menu.setOpen(true,false);save(root(),"autobash-compact-orbit",640,1100);for(View node:menu.destinations){assertTrue(node.getLeft()>=0);assertTrue(node.getRight()<=menu.getWidth());assertTrue(node.getTop()>=0);assertTrue(node.getBottom()<=menu.getHeight());assertTrue(node.getWidth()>=Ui.dp(a,48));assertTrue(node.getHeight()>=Ui.dp(a,48));}assertNotNull(find(root(),"Start session"));}
 @Test public void reduceMotionStopsAmbientChange(){NerveSurface v=new NerveSurface(a,true);v.layout(0,0,300,500);Bitmap first=draw(v,300,500);SystemClock.sleep(1200);Bitmap second=draw(v,300,500);assertTrue(first.sameAs(second));first.recycle();second.recycle();}
 @Test public void nervesReactToTimeAndTouch(){a.getSharedPreferences("config",0).edit().putBoolean("reduceMotion",false).commit();assertTrue(Ui.motion(a));NerveSurface v=new NerveSurface(a,true);v.layout(0,0,300,500);Bitmap first=draw(v,300,500);SystemClock.sleep(900);Bitmap second=draw(v,300,500);assertFalse(first.sameAs(second));MotionEvent e=MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,100,100,0);v.dispatchTouchEvent(e);Bitmap third=draw(v,300,500);assertFalse(second.sameAs(third));first.recycle();second.recycle();third.recycle();e.recycle();}
 @Test public void fastSearchDefaultsOnAndCanBeCompared(){OrbitMenu menu=findOrbit(root());menu.brain.performClick();menu.destinations[3].performClick();Switch toggle=(Switch)find(root(),"Fast candidate search");assertNotNull(toggle);assertTrue(toggle.isChecked());toggle.performClick();assertFalse(a.getSharedPreferences("config",0).getBoolean("hybridSearch",true));}
 @Test public void launcherBrainRenders()throws Exception{android.graphics.drawable.Drawable logo=a.getDrawable(com.pratik.imagetap.R.drawable.ic_launcher);Bitmap b=Bitmap.createBitmap(216,216,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(Ui.BG);logo.setBounds(0,0,216,216);logo.draw(c);int colored=0;for(int y=0;y<216;y++)for(int x=0;x<216;x++)if(b.getPixel(x,y)!=Ui.BG)colored++;assertTrue(colored>500);File f=new File("build/ui-previews/autobash-icon.png");try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 static OrbitMenu findOrbit(View v){if(v instanceof OrbitMenu)return (OrbitMenu)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){OrbitMenu r=findOrbit(((ViewGroup)v).getChildAt(i));if(r!=null)return r;}return null;}
 static View find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View r=find(((ViewGroup)v).getChildAt(i),text);if(r!=null)return r;}return null;}
 static Bitmap draw(View v,int w,int h){Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));return b;}
 static void save(View v,String name,int w,int h)throws Exception{v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);Bitmap b=draw(v,w,h);File f=new File("build/ui-previews/"+name+".png");f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
}
